import unittest
import kalkylator as kal  #filnamn

class TestKalkylator(unittest.TestCase):

    def test_addition(self):
        self.assertEqual(kal.addition(10,5), 15)

    def test_subtraktion(self):
        self.assertEqual(kal.subtraktion(10,3), 7)

    def test_multiplikation(self):
        self.assertEqual(kal.multiplikation(10,3), 30)

    def test_division(self):
        self.assertEqual(kal.division(10,2), 5)      

if __name__ == '__main__':
  unittest.main()

# Detta är filen med funktioner som ska testas
def addition(a,b):
	return a+b

def subtraktion(a,b):
	return a-b

def multiplikation(a,b):
	return a*b

def division(a,b):
	if( b == 0):
		raise ValueError("Ej delbart med 0")
	return a/b
